body:
{
  "pains": [
    {
      "id": "pain:no-badge-no-deal",
      "statement": "Deals we should win go to the competitor who already has the SOC 2 report, and we never get told that's why.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "A prospect's shortlist comes back and the company is not on it, or the deal parks in security review and stops moving.",
        "operational": "Someone senior stops selling and starts a compliance project: pick a platform, pick an auditor, chase policies, and wait months before the report exists.",
        "personal": null,
        "personal_note": "No public source shows what this costs the individual founder or sales lead. The quotes stop at company revenue ('clients that wouldn't be customers'). Looked in the May 2026 Ask HN thread, AWS Marketplace and Capterra reviews; founders post about the cost of the audit, not about what losing the deal did to them. Asked as q:pains-personal-rung."
      },
      "workflow": "The vendor shortlist stage of an enterprise procurement cycle: the buyer's team filters candidates on whether a SOC 2 report exists before a demo is ever booked, which is where Nelkins' team cut a field of headless CRM options down to Strapi.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A prospect's procurement team names SOC 2 as a hard requirement and filters the shortlist on it before evaluating the product.",
          "cites": ["src:11"]
        },
        {
          "event": "A direct competitor in the same category gets certified first, which turns the gap into a visible reason to lose.",
          "cites": ["src:12"]
        },
        {
          "event": "The company starts selling into finance or healthcare, where policy to reject uncertified vendors actually exists.",
          "cites": ["src:14"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "we absolutely have clients that wouldn't be customers if we didn't have SOC 2",
              "cites": ["src:5"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I doubt you could get it under $20k but that's the ballpark",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Revenue they can name: named accounts that would not have closed without the report, against a first-audit spend in the fifteen to twenty thousand range before any internal time.",
          "fears": "That the deals lost to a certified competitor are invisible, so the cost of waiting keeps growing without ever showing up in a forecast.",
          "dream_outcome": "The report exists before the question is asked, and the security requirement stops being a reason the shortlist gets shorter."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "you're definitely transparently losing sales",
              "cites": ["src:12"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "they were adamant that whatever platform we used _had_ to be SOC2 compliant",
              "cites": ["src:11"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "we went with Strapi solely because of this requirement",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Weeks of selling time spent arguing that the company is secure instead of demonstrating the product, in a conversation the certified competitor never has to have.",
          "fears": "That they will be the one who has to explain internally why a deal the team had already forecast went to a competitor on a checkbox.",
          "dream_outcome": "Hand over a report, clear security review in days, and go back to selling the product."
        }
      },
      "segments": ["seg:startup", "seg:scaling"],
      "feature_ref": "feat:automated",
      "feature_note": "Automated evidence collection is what compresses the time from 'we need a report' to 'we have one', which is the part of this pain a product can actually shorten. It does not touch the deals already lost while the company had nothing.",
      "cites": ["src:5", "src:11", "src:12", "src:14"]
    },
    {
      "id": "pain:questionnaire-treadmill",
      "statement": "Every enterprise deal arrives with a two-hundred-line security questionnaire, and having the SOC 2 report does not stop them sending it.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "A spreadsheet with two hundred-plus questions lands by email, attached to a deal that cannot move until it comes back.",
        "operational": "Someone answers it row by row, copying from a master spreadsheet of previous answers, and hand-edits the rows where this buyer asked something new.",
        "personal": null,
        "personal_note": "The public sources name the volume and the annoyance ('insane 200+ questionnaire') but not what it costs the person who fills it in - no source shows the evening, the missed deadline or the conversation with a manager. Searched the May 2026 SOC 2 thread, HN security-questionnaire comments and both review sites. Asked as q:pains-personal-rung."
      },
      "workflow": "The security review step of an enterprise deal: a 200-plus-row spreadsheet arrives by email, and one person answers it against a master spreadsheet of SOC 2 questions and previous answers before the deal can advance.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A deal reaches security review without a SOC 2 report on hand, which is when the long-form questionnaire gets sent instead.",
          "cites": ["src:9"]
        },
        {
          "event": "Selling into finance, healthcare or large enterprise, where a policy to reject uncertified vendors exists and the review is run properly.",
          "cites": ["src:14"]
        },
        {
          "event": "A hospital or other regulated customer insists on an independent third-party audit of its own, on top of whatever the vendor already holds.",
          "cites": ["src:17"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "without a SOC2 you will be asked to fill out an insane 200+ questionnaire",
              "cites": ["src:9"]
            },
            {
              "situation": "when_looking",
              "verbatim": "this is what you send to companies when they insist",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "the hardest part is paperwork and staff procedures",
              "cites": ["src:17"]
            }
          ],
          "costs_them": "Hours per deal transcribing answers they have already written down somewhere else, with no version of the work that carries over cleanly to the next buyer.",
          "fears": "That the answers drift apart across copies of the spreadsheet and one of them contradicts the others in front of a customer's security team.",
          "dream_outcome": "Send one thing that answers it, and only touch the handful of questions that are genuinely new."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "In my industry they still ask for the questionnaire even if you have a SOC2 report!",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "Questionnaire automation needs work. It does not provide good answers.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "The certification they sponsored does not deliver the exemption they sold internally, so the questionnaire workload survives the project that was meant to end it.",
          "fears": "That the answer the automation produces is wrong or generic enough to fail a security review they would have passed by hand.",
          "dream_outcome": "The report plus a page the customer can read settles most reviews, and the questionnaires that still arrive get answered accurately without a person retyping them."
        }
      },
      "segments": ["seg:startup", "seg:scaling", "seg:regulated"],
      "feature_ref": "feat:questionnaire",
      "feature_note": "Questionnaire automation aims squarely at this, and it is the one feature in brain/company that a paying reviewer criticised by name: 'Questionnaire automation needs work. It does not provide good answers.' The pain is confirmed and the fix is contested.",
      "cites": ["src:1", "src:8", "src:9", "src:10", "src:17"]
    },
    {
      "id": "pain:evidence-the-robot-cant-fetch",
      "statement": "The integrations pull maybe most of it, and then I spend hours hand-uploading scans and typing the risk register to clear the red.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "A dashboard of red items for documents the integrations cannot reach: scanned contracts, physical certificates, a risk register with nothing behind it.",
        "operational": "Chase the paper, scan it, upload it one file at a time, fill dropdowns by hand, and jump on calls with vendors and colleagues to walk them through uploading their own.",
        "personal": null,
        "personal_note": "Reviewers describe being nagged ('constantly yells at me') but no source states what the work costs the person outside their job - no evenings, no review conversation. Read AWS Marketplace review lists for Vanta and Drata and Capterra's Vanta reviews. Asked as q:pains-personal-rung."
      },
      "workflow": "Clearing red items on the controls dashboard in Vanta or Drata: everything the integrations cannot reach - scanned contracts, physical certificates, the risk register's five dropdowns per scenario - is typed or uploaded by hand before the auditor's document request list can be closed.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The audit window opens and the auditor's document request list arrives, turning outstanding red items into a deadline.",
          "cites": ["src:1"]
        },
        {
          "event": "A vendor or supplier has to be onboarded whose evidence exists only on paper, so nothing about it can be collected automatically.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "We waste hours manually uploading their physical food safety certificates into the system just to clear the annoying red dashboard errors.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "The automated dashboard constantly yells at me about missing documents until I manually upload a scanned copy.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Filling in the risk register by hand is slow with five dropdowns per scenario.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Hours a week of clerical work inside a product bought to remove clerical work, spent on exactly the evidence no integration can reach.",
          "fears": "That the red never actually goes away, so the dashboard stops being a signal and becomes background noise they learn to ignore.",
          "dream_outcome": "The platform collects what it can and asks for the rest once, in a batch, instead of holding the whole board red until each scan is in."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I find the SOC2 compliance process, especially uploading documents and viewing them, to be complex with Drata.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "team constantly has to jump on video calls just to hold their hands through uploading",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Their own time and their team's, spent supporting other people through an upload flow rather than on the controls the audit actually turns on.",
          "fears": "That the manual backlog is what makes the audit late, after they were the one who promised automation would prevent that.",
          "dream_outcome": "The people around them can get evidence in without a call, and the only items left red are the ones genuinely outstanding."
        }
      },
      "segments": ["seg:scaling", "seg:regulated"],
      "feature_ref": "feat:automated",
      "feature_note": "Automated evidence collection is the feature this pain sits against, and the complaints mark its boundary rather than deny it: buyers accept what the integrations reach and resent the manual remainder. Confidence is medium because both review sources are syndicated from G2, so this is closer to one review corpus than two independent ones.",
      "cites": ["src:1", "src:2"]
    },
    {
      "id": "pain:false-positive-fatigue",
      "statement": "The tool flags people as improperly offboarded when the exception was legitimate, and there is no clean way to tell it so.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "Failing tests and alerts for situations the tool does not model: a valid special case shows up as a control failure, alongside alerts that carry no context.",
        "operational": "Triage the board by hand every time, work out which red is real, and either leave a known-false failure standing or invent a workaround to silence it.",
        "personal": null,
        "personal_note": "Reviewers describe the tool's behaviour, not their own cost. No source shows what a board full of known-false failures does to the person who owns it or how they explain it to an auditor. Read AWS Marketplace Vanta and Drata review lists and Capterra Vanta reviews. Asked as q:pains-false-positives."
      },
      "workflow": "The recurring pass over the tests list and alert feed in Vanta or Drata, at the step where an offboarded user is flagged despite a valid exception and the reviewer has to decide whether the red is real before an auditor sees it.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "An employee or contractor offboards under a special case the control does not model, which is when the false failure appears.",
          "cites": ["src:1"]
        },
        {
          "event": "An integration ingests a large volume of data and the tests list starts showing stale status alongside the real failures.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "limited flexibility can create false positives",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Alerts can also feel noisy or lack enough context.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_looking",
              "verbatim": "giving users more control over notifications and tweaking integrations",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Time spent every cycle separating real failures from modelling gaps, on a board that is supposed to be the thing that tells them at a glance.",
          "fears": "That they stop reading the alerts, and the one failure that mattered sits in the same red pile as the ones that never did.",
          "dream_outcome": "Record the exception once, with a reason, and have the control go green and stay green until the exception stops being true."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "users being flagged as improperly offboarded when a valid special case applies",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Vanta often lacks simple options for handling exceptions",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Risk management can be more flexible",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Credibility: they signed off on a platform that now reports failures they know are wrong, in front of auditors and colleagues.",
          "fears": "That a known-false failure in the record has to be explained to an auditor, and explaining it costs more than the control was worth.",
          "dream_outcome": "Exceptions are first-class - documented, approved and visible - so the control set matches how the company actually works."
        }
      },
      "segments": ["seg:scaling", "seg:regulated"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company kills this; it is a pain the category creates. feat:access and feat:grc are where it shows up (offboarding checks, continuous monitoring between audits), which makes them the cause rather than the cure. What would kill it is first-class exception handling: a documented, approved, expiring suppression at control level. That absence is a finding for the positioning and offer steps, and a question for the founder.",
      "cites": ["src:1", "src:2", "src:3"]
    },
    {
      "id": "pain:passed-the-audit-still-guessing",
      "statement": "We got the badge in an afternoon of answering our own questions, and it tells me nothing about whether we're actually secure.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "A certification arrives after a process that felt like a self-assessment - nobody looked at the codebase, nobody checked the answers.",
        "operational": "Treat the report as a sales artifact and keep whatever real security work you were doing as a separate, unbudgeted track that the compliance project does not touch.",
        "personal": "The person who ran the process knows the badge means less than the customer reading it assumes, says so publicly, and carries that gap quietly into the next sales conversation.",
        "personal_note": "Grounded in abustamam, who runs the process and then writes that certified companies still get breached and 'this isnt really reassuring in itself'. Not extended beyond what that quote supports."
      },
      "workflow": "The annual audit cycle itself: answering the platform's own control questionnaire, collecting the report, then having nothing to say when an engineer asks what actually changed about the system's security between last year's badge and this one's.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A publicly certified company gets breached, which is when the gap between the badge and the posture becomes the thing everyone points at.",
          "cites": ["src:16"]
        },
        {
          "event": "An engineer or evaluator inside the company asks what the certification actually verified, and the honest answer is a self-questionnaire.",
          "cites": ["src:16"]
        }
      ],
      "who_feels": ["technical_evaluator", "champion"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The way we did it was scarily easy.",
              "cites": ["src:16"]
            },
            {
              "situation": "venting",
              "verbatim": "I could have lied and said yes to everything and still got compliant",
              "cites": ["src:16"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I got a shiny badge after about an hour of answering questions",
              "cites": ["src:16"]
            },
            {
              "situation": "venting",
              "verbatim": "there are many SOC2 compliant companies that get pwnd so this isnt really reassuring in itself",
              "cites": ["src:16"]
            }
          ],
          "costs_them": "The one artifact they are handed to prove security proves attendance instead, so they are back to judging posture with no evidence the process produced.",
          "fears": "A breach at a company holding the same badge, and having told customers the badge meant something.",
          "dream_outcome": "Evidence that controls actually held through the year, continuously, rather than a point-in-time attestation that a form was filled in."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "half of SOC 2 is kinda bull crap and half of it is really good healthy processes",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "Even though I agree SOC2 in practice is of dubious security value",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Internal capital spent selling a program half of which their own engineers think is theatre, which makes the next security budget harder to get.",
          "fears": "That the compliance program becomes known internally as the thing that consumes security budget without improving security.",
          "dream_outcome": "The controls that are genuinely good habits run continuously and visibly, so the program defends itself instead of needing defending."
        }
      },
      "segments": ["seg:startup", "seg:scaling"],
      "feature_ref": "feat:grc",
      "feature_note": "Continuous GRC - controls monitored between audits - is the direct answer to a point-in-time badge, and this is the clearest case in the map of a feature whose value buyers articulate before any vendor does. Note pain:false-positive-fatigue is the counterweight: continuous monitoring is also what generates the failures buyers say they cannot except out of.",
      "cites": ["src:5", "src:11", "src:16"]
    },
    {
      "id": "pain:the-answer-spreadsheet",
      "statement": "There's a master spreadsheet of security questions and answers that I keep updating and emailing out, and I've never once thought of it as a problem.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Nothing looks wrong. There is a documentation folder and a spreadsheet, and when a company insists, you send it.",
        "operational": "Maintain the documents and the master question-and-answer sheet by hand, add rows each time a new buyer asks something new, and re-send the file to every company that asks.",
        "personal": "About five hours a month in the first year, out of one person's own week, plus the two weeks a year that come back around every audit.",
        "personal_note": "Grounded in hughw's 'I spent a probably 5 hours a month the first year' and flippy_flops on post-first-audit upkeep. Both are the person's own time, stated by them; not extended beyond that."
      },
      "workflow": "Maintaining the master spreadsheet of SOC 2 questions and answers in a sheet alongside the procedure docs and network diagrams, and emailing the file to each company that insists, then editing it when the next one asks something the last one did not.",
      "type": "latent",
      "confidence": "low",
      "revealed_by": "feat:trust",
      "triggers": [
        {
          "event": "A new customer insists on proof, which is the moment the spreadsheet has to be found, updated and sent again.",
          "cites": ["src:8"]
        },
        {
          "event": "Expanding into healthcare or another regulated market, where vendor evaluation is heavier and documentation demands multiply.",
          "cites": ["src:18"]
        }
      ],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "a master spreadsheet with the \"soc 2\" questions (that you pick) and answers",
              "cites": ["src:8"]
            },
            {
              "situation": "when_looking",
              "verbatim": "this is what you send to companies when they insist",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "A private, hand-kept artifact that only they can update and only they can vouch for, which makes them the bottleneck on every buyer's security review.",
          "fears": "Nothing stated. They do not describe this as a risk at all, which is what makes the pain latent - it is presented as the sensible way to do it.",
          "dream_outcome": "Not stated in the sources. They are recommending the spreadsheet, not wishing it away; what a better version looks like is exactly what the Trust Center would have to show them."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I spent a probably 5 hours a month the first year",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "there is an initial upfront cost with regards to documentation",
              "cites": ["src:18"]
            }
          ],
          "costs_them": "Five hours a month in year one and a week or two a year after, absorbed as the cost of doing business rather than counted as a problem.",
          "fears": "Not shown. The tone in both sources is acceptance - 'it's all set up, very little until audit time' - rather than worry.",
          "dream_outcome": "Not stated. The nearest thing either says is that the work gets smaller after the first year, which is a lower cost, not a different way of working."
        }
      },
      "segments": ["seg:startup", "seg:regulated"],
      "feature_ref": "feat:trust",
      "feature_note": "The Trust Center is what would make this nameable: a public page a buyer reads without asking removes both the spreadsheet and the emailing. Marked latent because no source complains about the spreadsheet - lazyant recommends it as the answer, hughw and goopthink book the hours as normal cost. Confidence low: the evidence is a workaround treated as furniture across three sources, one of them from 2022, and nobody in public has called it a pain. q:pains-trust-center would settle it.",
      "cites": ["src:6", "src:8", "src:18"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "In the May 2026 Ask HN thread on getting SOC 2, practitioners name several platforms unprompted - Vanta, Thoropass - and argue about which to use and whether to buy at all, rather than asking whether tools exist. They know solutions exist; the open question is which one and whether it is worth it.",
      "cites": ["src:4", "src:5", "src:6", "src:15"]
    },
    "seg:scaling": {
      "level": "product",
      "rationale": "This segment is already inside the products: the reviewers on the AWS Marketplace and Capterra listings are paying users of Vanta and Drata comparing specific behaviours - alerts, exceptions, upload flows, UI changes - which is the vocabulary of people who know the product and are weighing whether to stay.",
      "cites": ["src:1", "src:2", "src:3"]
    }
  },
  "stats": [
    {
      "id": "stat:first-audit-cost",
      "stat": "A first SOC 2 Type 2 runs roughly $15,000 to $20,000 in audit fees for a very small company.",
      "scope": "Two founders posting in one May 2026 Hacker News thread about solo and very small companies. The conservative end is used: saluki's local-firm fee of around $15k, against flippy_flops' 'under $20k' ballpark. Excludes internal hours and the compliance platform subscription, which both flag separately as ongoing. Two posters in one thread is a thin base; not a survey.",
      "cites": ["src:5", "src:7"]
    },
    {
      "id": "stat:first-year-upkeep",
      "stat": "Compliance upkeep runs about five hours a month in the first year, dropping to one to two weeks of work a year once the first audit is behind you.",
      "scope": "Two founders describing their own time in the same May 2026 Hacker News thread, both post-first-audit: hughw on year one with Thoropass, flippy_flops on subsequent years. Self-reported, small companies, no platform named in common. Excludes the audit fee itself.",
      "cites": ["src:5", "src:6"]
    }
  ],
  "keywords": [
    "soc 2 type 2 solo founder",
    "how much does soc 2 cost",
    "is soc 2 worth it",
    "customer requires soc 2",
    "losing sales without soc 2",
    "security questionnaire template",
    "answer security questionnaires faster",
    "master spreadsheet security questionnaire",
    "soc 2 evidence collection manual",
    "vanta false positives offboarding",
    "vanta exceptions control",
    "vanta vs drata",
    "soc 2 auditor recommendation",
    "hipaa vendor audit cost",
    "trust center security page"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the first call with the last ten customers who closed, which of these did they name first, in their own words - deals stalling, the questionnaire load, the manual evidence, or the noise in the dashboard?",
      "why": "The whole map is built from public strangers. The order of pains here sets what the ICP, positioning and angles steps lead with, and one founder's answer would reorder it in a way no amount of review-reading can.",
      "would_change": "The order of pains[] and pains[].confidence"
    },
    {
      "id": "q:pains-personal-rung",
      "question": "When a customer describes the pain on a call, what do they say it costs them personally - the weekend, the review conversation, the thing they had to tell their boss?",
      "why": "Four of six pains have shape.personal null. The personal rung is what the angles step writes hooks from, and the public record almost never carries it. Nobody posts what the compliance project did to their week.",
